<?php
namespace App\Controllers; use App\Services\View; use App\Services\Database; final class AdminController { public function login(){ View::render('admin/login',['title'=>'Admin login']); } public function auth(){ \verify_csrf(); $st=Database::pdo()->prepare('SELECT * FROM admin_users WHERE email=?'); $st->execute([$_POST['email']??'']); $a=$st->fetch(); if(!$a||!password_verify($_POST['password']??'',$a['password_hash'])) \redirect('/admin/login'); session_regenerate_id(true); $_SESSION['admin']=['id'=>$a['id'],'name'=>$a['name'],'role'=>$a['role']]; \redirect('/admin'); } public function index(){ if(empty($_SESSION['admin'])) \redirect('/admin/login'); View::render('admin/index',['title'=>'Admin Dashboard']); } }
